            down = Input(type=1, ki=KeyboardInput(0, scan, 0x0004, 0, 0))
            up = Input(type=1, ki=KeyboardInput(0, scan, 0x0004 | 0x0002, 0, 0))
            if user32.SendInput(1, ctypes.byref(down), ctypes.sizeof(Input)) != 1:
