            if user32.SendInput(1, ctypes.byref(up), ctypes.sizeof(Input)) != 1:
                raise BridgeError("KEY_INPUT_FAILED", "SendInput key-up failed", {"win32_error": ctypes.get_last_error()})
            sent_units += 1
    finally:
        units = b""
    return sent_units


def desktop_type_text(p):
    value = str(p.get("text") if p.get("text") is not None else "")
    if len(value) > 10000:
        raise BridgeError("TEXT_TOO_LARGE", "gui_type is limited to 10000 characters per job")
    sent_units = _send_unicode_text(value)
    return {"characters": len(value), "utf16_units": sent_units}


def _secret_inbox():
    raw = str(os.environ.get(SECRET_INBOX_ENV) or "").strip()
    if not raw:
        return None
    try:
        path = Path(raw).expanduser()
        if not path.is_dir() or not os.access(path, os.R_OK | os.W_OK):
            return None
        return path
    except OSError:
        return None


def _secret_channel_available():
    return os.name == "nt" and _secret_inbox() is not None


def _validate_secret_target(target):
    if not isinstance(target, dict):
        raise BridgeError("SECRET_TARGET_REQUIRED", "params.target must be an object")
    mode = str(target.get("mode") or "").lower()
    if mode == "window":
        allowed = {"mode", "hwnd", "pid", "title", "visible_only", "first_match"}
        unknown = sorted(set(target) - allowed)
        if unknown:
            raise BridgeError("INVALID_SECRET_TARGET", "window target contains unsupported fields", {"fields": unknown})
        if target.get("hwnd") is None and not int(target.get("pid") or 0) and not str(target.get("title") or "").strip():
            raise BridgeError("SECRET_TARGET_REQUIRED", "window target requires hwnd, pid, or title")
    elif mode == "uia":
        allowed = {"mode", "selector", "hwnd", "pid", "title", "scope", "max_nodes", "max_depth", "wait_ms", "first_match"}
        unknown = sorted(set(target) - allowed)
        if unknown:
            raise BridgeError("INVALID_SECRET_TARGET", "UIA target contains unsupported fields", {"fields": unknown})
        _validate_uia_request({key: value for key, value in target.items() if key != "mode"}, "uia_focus")
    else:
        raise BridgeError("INVALID_SECRET_TARGET", "target.mode must be window or uia")
    return json.loads(json.dumps(target, sort_keys=True, ensure_ascii=False))


def _focus_secret_target(target):
    mode = str(target.get("mode") or "").lower()
    if mode == "window":
        return desktop_focus_window({key: value for key, value in target.items() if key != "mode"})
    return desktop_uia({key: value for key, value in target.items() if key != "mode"}, "uia_focus")


def _secret_replay_path(handle):
    return SECRET_REPLAY_DIR / (hashlib.sha256(handle.encode("ascii")).hexdigest() + ".json")


def _secret_time(value, code):
    value = str(value or "").strip()
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(value)
    except (TypeError, ValueError):
        raise BridgeError(code, "secret envelope timestamp is invalid")
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _claim_secret_envelope(handle, target):
    inbox = _secret_inbox()
    if inbox is None:
        raise BridgeError("SECRET_CHANNEL_UNAVAILABLE", "credential-safe secret input channel is unavailable")
    if not re.fullmatch(r"[A-Za-z0-9_-]{22,120}", handle):
        raise BridgeError("INVALID_SECRET_HANDLE", "secret handle format is invalid")

    replay = _secret_replay_path(handle)
    if replay.exists():
        raise BridgeError("SECRET_REPLAYED", "secret handle has already been consumed")

    source = inbox / (handle + ".json")
    claim = inbox / ("." + handle + ".claim-" + str(os.getpid()) + "-" + uuid.uuid4().hex + ".json")
    try:
        size = source.stat().st_size
    except FileNotFoundError:
        if replay.exists():
            raise BridgeError("SECRET_REPLAYED", "secret handle has already been consumed")
        raise BridgeError("SECRET_HANDLE_NOT_FOUND", "secret handle was not found")
    except OSError:
        raise BridgeError("SECRET_CHANNEL_UNAVAILABLE", "secret channel could not read the envelope")
    if size <= 0 or size > SECRET_MAX_BYTES:
        raise BridgeError("SECRET_ENVELOPE_SIZE_INVALID", "secret envelope size is outside the allowed bound")

    try:
        os.replace(source, claim)
    except FileNotFoundError:
        if replay.exists():
            raise BridgeError("SECRET_REPLAYED", "secret handle has already been consumed")
        raise BridgeError("SECRET_HANDLE_NOT_FOUND", "secret handle was already claimed or missing")
    except OSError:
        raise BridgeError("SECRET_CLAIM_FAILED", "secret envelope could not be claimed atomically")

    SECRET_REPLAY_DIR.mkdir(parents=True, exist_ok=True)
    atomic_write_text(
        replay,
        json.dumps(
            {"consumed_at": now(), "purpose": SECRET_PURPOSE, "destination": str(os.environ.get("COMPUTERNAME") or "heaven").casefold()},
            separators=(",", ":"),
        ),
    )

    raw = bytearray()
    envelope = None
    try:
        try:
            raw.extend(claim.read_bytes())
            envelope = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            raise BridgeError("SECRET_ENVELOPE_INVALID", "secret envelope is not valid UTF-8 JSON")
        if not isinstance(envelope, dict) or envelope.get("schema") != SECRET_SCHEMA:
            raise BridgeError("SECRET_ENVELOPE_INVALID", "secret envelope schema is invalid")
        if str(envelope.get("purpose") or "") != SECRET_PURPOSE:
            raise BridgeError("SECRET_PURPOSE_MISMATCH", "secret envelope purpose does not match")
        expected_host = str(os.environ.get("COMPUTERNAME") or "heaven").casefold()
        if str(envelope.get("destination") or "").casefold() != expected_host:
            raise BridgeError("SECRET_DESTINATION_MISMATCH", "secret envelope destination does not match this worker")
        if envelope.get("target") != target:
            raise BridgeError("SECRET_TARGET_MISMATCH", "secret envelope target binding does not match")

        current = utcnow()
        created = _secret_time(envelope.get("created_at"), "SECRET_CREATED_AT_INVALID")
        expires = _secret_time(envelope.get("expires_at"), "SECRET_EXPIRES_AT_INVALID")
        if (created - current).total_seconds() > 30:
            raise BridgeError("SECRET_NOT_YET_VALID", "secret envelope creation time is in the future")
        if expires <= current:
            raise BridgeError("SECRET_EXPIRED", "secret envelope has expired")
        ttl = (expires - created).total_seconds()
        if ttl <= 0 or ttl > SECRET_MAX_TTL:
            raise BridgeError("SECRET_TTL_INVALID", "secret envelope TTL is outside the allowed bound")

        value = envelope.get("value")
        if not isinstance(value, str):
            raise BridgeError("SECRET_VALUE_INVALID", "secret envelope value must be text")
        if len(value) > SECRET_MAX_CHARS:
            raise BridgeError("SECRET_VALUE_TOO_LARGE", "secret value exceeds the allowed bound")

        try:
            claim.unlink()
        except OSError:
            raise BridgeError("SECRET_CLEANUP_FAILED", "claimed secret envelope could not be removed")
        claim = None
        return value
    finally:
        for index in range(len(raw)):
            raw[index] = 0
        if claim is not None:
            try:
                claim.unlink()
            except OSError:
                pass
        envelope = None


def desktop_type_secret(p):
    handle = str(p.get("handle") or "").strip()
    if not handle:
        raise BridgeError("SECRET_HANDLE_REQUIRED", "params.handle is required")
    target = _validate_secret_target(p.get("target"))
    _focus_secret_target(target)
    value = _claim_secret_envelope(handle, target)
    try:
        _send_unicode_text(value)
    except Exception:
        raise BridgeError("SECRET_INPUT_FAILED", "secret was consumed but keyboard input failed; create a new handle")
    finally:
        value = None
    return {"consumed": True, "typed": True}


